def solve(n, edges):
    parent = list(range(n))
    size = [1] * n
    def find(x):
        while x != parent[x]:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    components = n
    for a, b in edges:
        a, b = find(a), find(b)
        if a == b:
            continue
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]
        components -= 1
    return components

import heapq

def solve(graph, source):
    distance = [float("inf")] * len(graph)
    distance[source] = 0
    heap = [(0, source)]
    while heap:
        cost, node = heapq.heappop(heap)
        if cost != distance[node]:
            continue
        for neighbor, weight in graph[node]:
            candidate = cost + weight
            if candidate < distance[neighbor]:
                distance[neighbor] = candidate
                heapq.heappush(heap, (candidate, neighbor))
    return [None if d == float("inf") else d for d in distance]

def solve(n, flights, source, target, k):
    distance = [float("inf")] * n
    distance[source] = 0
    for _ in range(k + 1):
        next_distance = distance.copy()
        for a, b, price in flights:
            next_distance[b] = min(next_distance[b], distance[a] + price)
        distance = next_distance
    return -1 if distance[target] == float("inf") else distance[target]

