from collections import deque

def solve(graph, source):
    dist = [float("inf")] * len(graph)
    dist[source] = 0
    queue = deque([(0, source)])
    while queue:
        cost, node = queue.popleft()
        if cost != dist[node]:
            continue
        for neighbor, weight in graph[node]:
            candidate = cost + weight
            if candidate < dist[neighbor]:
                dist[neighbor] = candidate
                item = (candidate, neighbor)
                if weight == 0:
                    queue.appendleft(item)
                else:
                    queue.append(item)
    return [None if d == float("inf") else d for d in dist]

def solve(nums, left, right):
    tree = [0] * (len(nums) + 1)
    def add(index, delta):
        index += 1
        while index < len(tree):
            tree[index] += delta
            index += index & -index
    def prefix(end):
        total = 0
        while end > 0:
            total += tree[end]
            end -= end & -end
        return total
    for index, value in enumerate(nums):
        add(index, value)
    return prefix(right) - prefix(left)
